+import { db } from "../../lib/db";
+import { requireAccount } from "../../lib/session";
+
+export async function exportInvoices(request: Request): Promise<Response> {
+  const account = await requireAccount(request);
+  const invoices = await db.invoices.listByAccount(account.id);
+  const rows = invoices.map((invoice) => [invoice.id, invoice.issuedAt, invoice.totalCents, invoice.currency].join(","));
+  return new Response(["id,issued_at,total_cents,currency", ...rows].join("\n"), {
+    headers: { "content-type": "text/csv", "content-disposition": "attachment; filename=invoices.csv" },
+  });
+}
